    public async Task SaveInstallationAsync(EmulatorInstallation installation, CancellationToken cancellationToken = default)
    {
        if (!File.Exists(installation.ExecutablePath)) throw new FileNotFoundException("The selected emulator executable does not exist.", installation.ExecutablePath);
        string path = Path.GetFullPath(installation.ExecutablePath);
        await using SqliteConnection connection = await factory.OpenAsync(cancellationToken).ConfigureAwait(false);
        await using SqliteCommand command = connection.CreateCommand();
        command.CommandText = "INSERT INTO EmulatorInstallations(Id,AdapterId,DisplayName,ExecutablePath,NormalizedExecutablePath,Version,Architecture,InstallationDirectory,UserDataDirectory,Enabled,IsPortable,ArgumentsOverride,CapabilitiesJson,ValidationStatus,AddedAtUtc,UpdatedAtUtc,LastValidatedAtUtc) VALUES($id,$adapter,$name,$path,$normalized,$version,$arch,$directory,$userData,$enabled,$portable,$arguments,$capabilities,$status,$added,$updated,$validated) ON CONFLICT(Id) DO UPDATE SET AdapterId=excluded.AdapterId,DisplayName=excluded.DisplayName,ExecutablePath=excluded.ExecutablePath,NormalizedExecutablePath=excluded.NormalizedExecutablePath,Version=excluded.Version,Architecture=excluded.Architecture,InstallationDirectory=excluded.InstallationDirectory,UserDataDirectory=excluded.UserDataDirectory,Enabled=excluded.Enabled,IsPortable=excluded.IsPortable,ArgumentsOverride=excluded.ArgumentsOverride,CapabilitiesJson=excluded.CapabilitiesJson,ValidationStatus=excluded.ValidationStatus,UpdatedAtUtc=excluded.UpdatedAtUtc,LastValidatedAtUtc=excluded.LastValidatedAtUtc;";
        Add(command,"$id",installation.Id);Add(command,"$adapter",installation.AdapterId);Add(command,"$name",installation.DisplayName);Add(command,"$path",path);Add(command,"$normalized",Normalize(path));Add(command,"$version",installation.Version);Add(command,"$arch",installation.Architecture);Add(command,"$directory",Path.GetFullPath(installation.InstallationDirectory));Add(command,"$userData",FullPath(installation.UserDataDirectory));Add(command,"$enabled",installation.Enabled?1:0);Add(command,"$portable",installation.IsPortable?1:0);Add(command,"$arguments",installation.ArgumentsOverride);Add(command,"$capabilities",JsonSerializer.Serialize((int)installation.DetectedCapabilities,JsonOptions));Add(command,"$status",(int)installation.ValidationStatus);Add(command,"$added",installation.AddedAtUtc.ToUniversalTime().ToString("O"));Add(command,"$updated",installation.UpdatedAtUtc.ToUniversalTime().ToString("O"));Add(command,"$validated",installation.LastValidatedAtUtc?.ToUniversalTime().ToString("O"));
        await command.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);
    }

    public async Task RelinkInstallationAsync(string id, string executablePath, EmulatorProbeResult probe, CancellationToken cancellationToken = default)
    {
        string path = Path.GetFullPath(executablePath);
        if (!File.Exists(path)) throw new FileNotFoundException("The replacement emulator executable does not exist.", path);
        await using SqliteConnection connection = await factory.OpenAsync(cancellationToken).ConfigureAwait(false);
        await using SqliteCommand command = connection.CreateCommand(); command.CommandText = "UPDATE EmulatorInstallations SET ExecutablePath=$path,NormalizedExecutablePath=$normalized,InstallationDirectory=$directory,Version=$version,CapabilitiesJson=$capabilities,ValidationStatus=$status,UpdatedAtUtc=$now,LastValidatedAtUtc=$now WHERE Id=$id;";
        Add(command,"$path",path);Add(command,"$normalized",Normalize(path));Add(command,"$directory",Path.GetDirectoryName(path)!);Add(command,"$version",probe.Version);Add(command,"$capabilities",JsonSerializer.Serialize((int)probe.Capabilities,JsonOptions));Add(command,"$status",(int)(probe.Succeeded?EmulatorValidationStatus.Valid:EmulatorValidationStatus.ProbeFailed));Add(command,"$now",DateTime.UtcNow.ToString("O"));Add(command,"$id",id);
        if (await command.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false) == 0) throw new KeyNotFoundException("The emulator installation was not found.");
    }

