        DateTime now=DateTime.UtcNow;
        await using(SqliteCommand command=connection.CreateCommand()){command.Transaction=tx;command.CommandText="INSERT INTO GameSources(Id,Name,FolderPath,NormalizedFolderPath,PlatformId,IncludeSubfolders,Enabled,FollowSymbolicLinks,ScanHiddenFiles,AdapterPreferenceId,CreatedAtUtc,UpdatedAtUtc,LastSuccessfulScanAtUtc) VALUES($id,$name,$path,$normalized,$platform,$recursive,$enabled,$links,$hidden,$adapter,$created,$updated,$scanned) ON CONFLICT(Id) DO UPDATE SET Name=excluded.Name,FolderPath=excluded.FolderPath,NormalizedFolderPath=excluded.NormalizedFolderPath,PlatformId=excluded.PlatformId,IncludeSubfolders=excluded.IncludeSubfolders,Enabled=excluded.Enabled,FollowSymbolicLinks=excluded.FollowSymbolicLinks,ScanHiddenFiles=excluded.ScanHiddenFiles,AdapterPreferenceId=excluded.AdapterPreferenceId,UpdatedAtUtc=excluded.UpdatedAtUtc;";Add(command,"$id",source.Id);Add(command,"$name",source.Name);Add(command,"$path",folder);Add(command,"$normalized",Normalize(folder));Add(command,"$platform",source.PlatformId);Add(command,"$recursive",source.IncludeSubfolders?1:0);Add(command,"$enabled",source.Enabled?1:0);Add(command,"$links",source.FollowSymbolicLinks?1:0);Add(command,"$hidden",source.ScanHiddenFiles?1:0);Add(command,"$adapter",source.AdapterPreferenceId);Add(command,"$created",source.CreatedAtUtc.ToUniversalTime().ToString("O"));Add(command,"$updated",source.UpdatedAtUtc.ToUniversalTime().ToString("O"));Add(command,"$scanned",source.LastSuccessfulScanAtUtc?.ToUniversalTime().ToString("O"));await command.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);}
        await using(SqliteCommand command=connection.CreateCommand()){command.Transaction=tx;command.CommandText="INSERT INTO ProviderLibrarySources(Id,ProviderId,ExternalId,Path,NormalizedPath,Enabled,FirstSeenAtUtc,LastSeenAtUtc) VALUES($id,'emulation',$id,$path,$normalized,$enabled,$now,$now) ON CONFLICT(Id) DO UPDATE SET Path=excluded.Path,NormalizedPath=excluded.NormalizedPath,Enabled=excluded.Enabled,LastSeenAtUtc=excluded.LastSeenAtUtc;";Add(command,"$id",source.Id);Add(command,"$path",folder);Add(command,"$normalized",Normalize(folder));Add(command,"$enabled",source.Enabled?1:0);Add(command,"$now",now.ToString("O"));await command.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);}
        await tx.CommitAsync(cancellationToken).ConfigureAwait(false);
    }

