    public async Task<EmulatedGameImportResult> ImportAsync(GameSource source,IReadOnlyCollection<EmulatedGameImportSelection> selections,CancellationToken cancellationToken=default)
    {
        int added=0,updated=0,skipped=0,failed=0;List<string> errors=[];
        await using SqliteConnection connection=await factory.OpenAsync(cancellationToken).ConfigureAwait(false);await using SqliteTransaction tx=(SqliteTransaction)await connection.BeginTransactionAsync(cancellationToken).ConfigureAwait(false);
        string platformDisplayName=await ScalarAsync(connection,tx,"SELECT Name FROM EmulatorPlatforms WHERE Id=$platform;",c=>Add(c,"$platform",source.PlatformId),cancellationToken).ConfigureAwait(false)??source.PlatformId;
        foreach(EmulatedGameImportSelection selection in selections)
        {
            cancellationToken.ThrowIfCancellationRequested();if(!selection.Import){skipped++;continue;}
            await ExecuteTxAsync(connection,tx,"SAVEPOINT import_item;",cancellationToken).ConfigureAwait(false);
            try
            {
                string? existing=await ScalarAsync(connection,tx,"SELECT LibraryItemId FROM EmulatedGameSources WHERE PlatformId=$platform AND NormalizedGamePath=$path;",c=>{Add(c,"$platform",selection.Game.PlatformId);Add(c,"$path",selection.Game.NormalizedGamePath);},cancellationToken).ConfigureAwait(false);
                if(existing is not null){await UpdateGameMetadataAsync(connection,tx,selection.Game,cancellationToken).ConfigureAwait(false);await ExecuteTxAsync(connection,tx,"RELEASE import_item;",cancellationToken).ConfigureAwait(false);updated++;continue;}
                string itemId=selection.LinkToLibraryItemId??Guid.NewGuid().ToString("N");string gameId=Guid.NewGuid().ToString("N");string targetId=Guid.NewGuid().ToString("N");DateTime now=DateTime.UtcNow;
                if(selection.LinkToLibraryItemId is null)
                {
                    await using SqliteCommand item=connection.CreateCommand();item.Transaction=tx;item.CommandText="INSERT INTO LibraryItems(Id,Title,SortTitle,Subtitle,ContentType,Favorite,Hidden,AddedAtUtc,UpdatedAtUtc,TotalPlaytimeSeconds,DefaultLaunchTargetId) VALUES($id,$title,$title,$subtitle,$type,0,0,$now,$now,0,$target);";Add(item,"$id",itemId);Add(item,"$title",selection.Game.SuggestedTitle);Add(item,"$subtitle",platformDisplayName);Add(item,"$type",(int)ContentType.Game);Add(item,"$now",now.ToString("O"));Add(item,"$target",targetId);await item.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);
                }
                await using(SqliteCommand game=connection.CreateCommand()){game.Transaction=tx;game.CommandText="INSERT INTO EmulatedGameSources(Id,LibraryItemId,PlatformId,GamePath,NormalizedGamePath,FileExtension,FileSize,FileModifiedAtUtc,GameIdentifier,IdentificationConfidence,Region,Revision,DiscNumber,DiscCount,GameSourceId,PreferredEmulatorInstallationId,LaunchProfileId,Available,FirstSeenAtUtc,LastSeenAtUtc) VALUES($id,$item,$platform,$path,$normalized,$extension,$size,$modified,$identifier,$confidence,$region,$revision,$disc,$discCount,$source,$emulator,NULL,1,$now,$now);";Add(game,"$id",gameId);Add(game,"$item",itemId);Add(game,"$platform",selection.Game.PlatformId);Add(game,"$path",selection.Game.GamePath);Add(game,"$normalized",selection.Game.NormalizedGamePath);Add(game,"$extension",selection.Game.FileExtension);Add(game,"$size",selection.Game.FileSize);Add(game,"$modified",selection.Game.FileModifiedAtUtc.ToUniversalTime().ToString("O"));Add(game,"$identifier",selection.Game.Identification.GameIdentifier);Add(game,"$confidence",(int)selection.Game.Identification.Confidence);Add(game,"$region",selection.Game.Identification.Region);Add(game,"$revision",selection.Game.Identification.Revision);Add(game,"$disc",selection.Game.Identification.DiscNumber);Add(game,"$discCount",selection.Game.Identification.DiscCount);Add(game,"$source",source.Id);Add(game,"$emulator",selection.Game.PreferredEmulatorInstallationId??source.AdapterPreferenceId);Add(game,"$now",now.ToString("O"));await game.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);}
                await using(SqliteCommand target=connection.CreateCommand()){target.Transaction=tx;target.CommandText="INSERT INTO LaunchTargets(Id,LibraryItemId,Name,LaunchType,HideFrontendWhileRunning,RestoreFrontendAfterExit,CreatedAtUtc,UpdatedAtUtc,ProviderId,IsEnabled,UserManaged,EmulatedGameSourceId,EmulatorInstallationId) VALUES($id,$item,'Emulation',$type,1,1,$now,$now,'emulation',1,0,$game,$emulator);";Add(target,"$id",targetId);Add(target,"$item",itemId);Add(target,"$type",(int)LaunchType.Emulator);Add(target,"$now",now.ToString("O"));Add(target,"$game",gameId);Add(target,"$emulator",selection.Game.PreferredEmulatorInstallationId??source.AdapterPreferenceId);await target.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);}
                string providerItem=selection.Game.PlatformId+"|"+selection.Game.NormalizedGamePath;
                await using(SqliteCommand provider=connection.CreateCommand()){provider.Transaction=tx;provider.CommandText="INSERT INTO LibraryItemSources(Id,LibraryItemId,ProviderId,ProviderItemId,ProviderLibrarySourceId,InstallationPath,Installed,ProviderDataJson,FirstSeenAtUtc,LastSeenAtUtc) VALUES($id,$item,'emulation',$providerItem,$source,$path,1,$data,$now,$now);";Add(provider,"$id",Guid.NewGuid().ToString("N"));Add(provider,"$item",itemId);Add(provider,"$providerItem",providerItem);Add(provider,"$source",source.Id);Add(provider,"$path",selection.Game.GamePath);Add(provider,"$data",JsonSerializer.Serialize(new{selection.Game.PlatformId,selection.Game.FileExtension},JsonOptions));Add(provider,"$now",now.ToString("O"));await provider.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);}
                if(selection.Game.ArtworkCandidates is not null)await InsertArtworkAsync(connection,tx,itemId,selection.Game.ArtworkCandidates,now,cancellationToken).ConfigureAwait(false);
                await ExecuteTxAsync(connection,tx,"RELEASE import_item;",cancellationToken).ConfigureAwait(false);added++;
            }
            catch(Exception exception) when(exception is SqliteException or IOException or UnauthorizedAccessException){await ExecuteTxAsync(connection,tx,"ROLLBACK TO import_item; RELEASE import_item;",CancellationToken.None).ConfigureAwait(false);failed++;errors.Add($"{selection.Game.SuggestedTitle}: {exception.Message}");}
        }
        await tx.CommitAsync(cancellationToken).ConfigureAwait(false);return new(added,updated,skipped,failed,errors);
    }

