        await using SqliteConnection connection=await factory.OpenAsync(cancellationToken).ConfigureAwait(false);await using SqliteTransaction tx=(SqliteTransaction)await connection.BeginTransactionAsync(cancellationToken).ConfigureAwait(false);int updated=0,missing=0;HashSet<string> seen=scan.Games.Select(g=>g.NormalizedGamePath).ToHashSet(StringComparer.OrdinalIgnoreCase);
        foreach(DiscoveredGame game in scan.Games){await UpdateGameMetadataAsync(connection,tx,game,cancellationToken).ConfigureAwait(false);updated++;}
        await using(SqliteCommand read=connection.CreateCommand()){read.Transaction=tx;read.CommandText="SELECT Id,NormalizedGamePath FROM EmulatedGameSources WHERE GameSourceId=$source;";Add(read,"$source",scan.Source.Id);List<string> absent=[];await using(SqliteDataReader reader=await read.ExecuteReaderAsync(cancellationToken).ConfigureAwait(false)){while(await reader.ReadAsync(cancellationToken).ConfigureAwait(false))if(!seen.Contains(reader.GetString(1)))absent.Add(reader.GetString(0));}foreach(string id in absent){await using SqliteCommand mark=connection.CreateCommand();mark.Transaction=tx;mark.CommandText="UPDATE EmulatedGameSources SET Available=0 WHERE Id=$id; UPDATE LaunchTargets SET IsEnabled=0 WHERE EmulatedGameSourceId=$id; UPDATE LibraryItemSources SET Installed=0 WHERE ProviderId='emulation' AND LibraryItemId=(SELECT LibraryItemId FROM EmulatedGameSources WHERE Id=$id);";Add(mark,"$id",id);await mark.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);missing++;}}
        await using(SqliteCommand source=connection.CreateCommand()){source.Transaction=tx;source.CommandText="UPDATE GameSources SET LastSuccessfulScanAtUtc=$now,UpdatedAtUtc=$now WHERE Id=$id;";Add(source,"$now",scan.CompletedAtUtc.ToUniversalTime().ToString("O"));Add(source,"$id",scan.Source.Id);await source.ExecuteNonQueryAsync(cancellationToken).ConfigureAwait(false);}await tx.CommitAsync(cancellationToken).ConfigureAwait(false);return new(0,updated,missing,0,[]);
    }

